import math

def f(n):
    """Calculates f(n), the odd part of n."""
    if n <= 0:
        raise ValueError("n must be positive")
    m = 0
    while n > 0 and n % 2 == 0:
        n //= 2
        m += 1
    return n

def check_condition(u, v):
    """Checks if the condition holds for given u and v."""
    if u <= 0 or v <= 0:
        return False

    for k in range(v):
        # Calculate the difference: f(u+v+k) - f(u+k)
        diff = f(u + v + k) - f(u + k)
        if diff % 4 != 0:
            return False
    return True

v_values = [1, 2, 3, 4, 5]
results = {}
U_MAX = 100 # Search limit for u

print("Starting investigation...")

for v in v_values:
    smallest_u = None
    for u in range(1, U_MAX + 1):
        if check_condition(u, v):
            smallest_u = u
            break

    results[v] = smallest_u

print("\n--- Results ---")
for v, u in results.items():
    print(f"v = {v}: Smallest u found = {u}" if u is not None else f"v = {v}: Not found up to u = {U_MAX}")

